import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *
T = {"pathophysiology": "How it works (mechanism of action)"}

E('emollients',
  titles=T,
  kf=["**Emollients** restore the skin barrier: the foundation of treatment for eczema, psoriasis, ichthyosis and dry skin.",
      "Types run from lotions (light, more water) through creams and gels to **ointments** (greasiest, most occlusive, fewest preservatives).",
      "Use **liberally and often**: adults with eczema may need about 250–500 g a week; apply in the direction of hair growth.",
      "Use as a **soap substitute**; leave 15–30 minutes between emollient and topical steroid.",
      "**Fire risk**: paraffin-based (and other) emollients dried on fabric are flammable; warn about naked flames and smoking (MHRA)."],
  myths=["**\"Emollients are just moisturisers, optional\"**: regular use reduces flares and steroid use.", "**\"Aqueous cream is a good emollient\"**: it contains sodium lauryl sulfate, an irritant; avoid as a leave-on."],
  patho_lead="Emollients work by **occluding, humectant attraction of water and replacing lipids**.",
  mech=[("Occlusion", "Oily layers (paraffin, petrolatum) slow transepidermal water loss.", "v3-eczema-barrier-section.jpg", "A leaky barrier loses water and lets irritants in; emollients seal it."),
        ("Humectants", "Urea, glycerol and lactic acid draw water into the stratum corneum."),
        ("Lipid replacement", "Ceramides and fatty acids refill gaps between corneocytes."),
        ("Choice by greasiness", "More oil = more occlusion but less cosmetic acceptability.", "v3-emollient-spectrum.jpg", "Spectrum from light lotions to greasy ointments."),
        ("Technique", "Smooth on downwards in the direction of hair growth to avoid folliculitis.", "v3-emollient-strokes.jpg", "Apply in long downward strokes.")],
  comp=["Folliculitis, irritant reactions (preservatives, lanolin), slipping and falls, fire risk."],
  prog=["Ongoing, lifelong in chronic conditions."],
  see_also=["eczema-dermatitis", "itch-xerosis-older-adults", "topical-corticosteroids", "psoriasis", "hand-eczema"])

E('topical-corticosteroids',
  titles=T,
  kf=["Potency ladder (UK): **mild** (hydrocortisone 1%), **moderate** (clobetasone butyrate 0.05%), **potent** (betamethasone valerate 0.1%, mometasone 0.1%), **very potent** (clobetasol propionate 0.05%).",
      "Match potency to **site and severity**: mild on face and folds, potent on body, very potent on palms and soles for short courses.",
      "Dose with **fingertip units**: 1 FTU ≈ 0.5 g covers two adult palms (about 2% body surface).",
      "Usually once or twice daily; for eczema, treat flares fully then step down or use **weekend (proactive) therapy**.",
      "Side effects come from misuse: atrophy, striae, perioral dermatitis, steroid rosacea, **topical steroid withdrawal**; under-treatment from **steroid phobia** is commoner."],
  myths=["**\"Steroid creams thin the skin, so use as little as possible\"**: correct potency for a short course is safe; under-treatment prolongs flares."],
  patho_lead="Corticosteroids **switch off inflammatory genes** in skin cells.",
  mech=[("Receptor binding", "Steroids cross the cell membrane and bind the glucocorticoid receptor."),
        ("Gene regulation", "The complex suppresses NF-κB and AP-1 (inflammatory genes) and induces anti-inflammatory proteins."),
        ("Effects", "Anti-inflammatory, immunosuppressive, vasoconstrictive and antiproliferative effects."),
        ("Absorption by site", "Thin skin (eyelids, genitals, folds) absorbs far more than palms and soles.", "v3-steroid-absorption-map.jpg", "Relative absorption varies widely by body site."),
        ("Atrophy with misuse", "Prolonged potent use thins epidermis and dermal collagen.", "v3-steroid-atrophy-section.jpg", "Steroid atrophy: thinned epidermis and dermis."),
        ("Dosing", "Fingertip units guide quantity.", "v3-fingertip-unit.jpg", "One fingertip unit.")],
  comp=["Atrophy, striae, telangiectasia, acne, rosacea, perioral dermatitis, infection masking (tinea incognito), HPA suppression (rare, large amounts)."],
  prog=["Safe and effective when the right potency is used for the right time."],
  see_also=["eczema-dermatitis", "emollients", "psoriasis", "perioral-dermatitis", "rosacea"])

E('retinoids',
  titles=T,
  kf=["**Topical retinoids** (adapalene, tretinoin, tazarotene) treat comedonal and inflammatory acne and photoageing.",
      "**Isotretinoin** (oral) for severe or scarring acne: dermatology-initiated, with the **Pregnancy Prevention Programme** and mood monitoring (MHRA).",
      "**Acitretin** for psoriasis and keratinisation disorders: avoid pregnancy for **3 years** after stopping.",
      "Topical retinoids are contraindicated in pregnancy and in women planning pregnancy (UK).",
      "Start low, apply thinly (pea-sized amount for the face), expect irritation for 2–4 weeks; use sunscreen."],
  myths=["**\"Retinoids thin the skin\"**: they thin the stratum corneum but thicken the epidermis and increase collagen."],
  patho_lead="Retinoids act on **nuclear retinoic acid receptors** to normalise how skin cells grow and shed.",
  mech=[("Receptors", "Retinoids bind RAR and RXR nuclear receptors and alter gene expression."),
        ("Normal keratinisation", "Reduce follicular plugging and comedones."),
        ("Anti-inflammatory", "Reduce TLR-2 expression and inflammatory signalling."),
        ("Sebum reduction (isotretinoin)", "Oral isotretinoin shrinks sebaceous glands dramatically.", "v3-sebaceous-shrink.jpg", "Isotretinoin shrinks sebaceous glands."),
        ("Application", "A pea-sized amount covers the whole face.", "v3-pea-sized-face.jpg", "Pea-sized amount for the whole face.")],
  comp=["Irritation, dryness, photosensitivity; teratogenicity; isotretinoin: dry lips and eyes, raised lipids and liver enzymes, mood changes."],
  prog=["Topical: improvement over 8–12 weeks. Isotretinoin: long remission in most."],
  see_also=["acne-vulgaris", "photoageing", "psoriasis", "acne-prescribing-combined-pill", "cosmetic-procedures"])

E('biologics-systemics',
  titles=T,
  kf=["Conventional systemics: **methotrexate** (weekly), ciclosporin, acitretin, azathioprine, mycophenolate; biologics target specific cytokines.",
      "Psoriasis biologics: TNF-α (adalimumab), IL-17 (secukinumab, ixekizumab, bimekizumab), IL-23 (guselkumab, risankizumab); eczema: dupilumab, tralokinumab, JAK inhibitors.",
      "Methotrexate is **once weekly**: prescribing errors (daily dosing) are fatal; folic acid on another day; monitor FBC, LFT, U&E.",
      "Screen before biologics: TB (IGRA), hepatitis B/C, HIV; avoid live vaccines.",
      "Infection on immunosuppressants needs early review; record specialist drugs in the GP record."],
  myths=["**\"Biologics are just stronger steroids\"**: they block one immune pathway, with different risks."],
  patho_lead="Systemic drugs and biologics **interrupt the immune circuits** that drive chronic skin inflammation.",
  mech=[("IL-23/Th17 axis", "Dendritic cell IL-23 sustains Th17 cells that release IL-17, driving psoriasis.", "v3-il23-th17-axis.jpg", "The IL-23/Th17 axis targeted by psoriasis biologics."),
        ("Th2 axis", "IL-4 and IL-13 drive atopic eczema; dupilumab blocks the IL-4 receptor α."),
        ("JAK–STAT", "Many cytokine receptors signal through JAKs; oral JAK inhibitors block several at once."),
        ("Antimetabolites", "Methotrexate inhibits folate pathways in rapidly dividing immune cells.", "v3-methotrexate-weekly.jpg", "Methotrexate is taken once a week.")],
  comp=["Infection (including TB reactivation), cytopenias, liver toxicity, kidney toxicity (ciclosporin), conjunctivitis (dupilumab), thrombosis risk (JAK inhibitors)."],
  prog=["Most patients achieve major improvement; treatment is long-term."],
  see_also=["psoriasis", "eczema-dermatitis", "hidradenitis-suppurativa", "vitamin-d-tar-phototherapy", "urticaria-angioedema"])

E('vitamin-d-tar-phototherapy',
  titles=T,
  kf=["**Vitamin D analogues** (calcipotriol, calcitriol) are first-line topicals for plaque psoriasis, often combined with a potent steroid.",
      "**Coal tar** is an older, effective but messy option for scalp and plaque psoriasis.",
      "**Narrowband UVB** (NB-UVB, 311 nm) for psoriasis, eczema, vitiligo; **PUVA** (psoralen + UVA) for thicker or resistant disease.",
      "Phototherapy is usually 2–3 times a week for 6–10 weeks; cumulative dose increases skin cancer risk (especially PUVA: SCC).",
      "Calcipotriol: max about 100 g a week in adults (hypercalcaemia risk with more); irritating on face and folds."],
  myths=["**\"Sunbeds are like phototherapy\"**: sunbeds emit mainly UVA, are unregulated and raise melanoma risk."],
  patho_lead="These treatments slow **keratinocyte overgrowth** and **suppress skin T cells**.",
  mech=[("Vitamin D receptor", "Calcipotriol binds the VDR, normalising keratinocyte proliferation and differentiation."),
        ("Tar", "Coal tar activates the aryl hydrocarbon receptor, reducing inflammation and scale."),
        ("UVB", "UVB penetrates the epidermis, causing T-cell apoptosis and immunosuppression.", "v3-uvb-uva-depth.jpg", "UVB acts in the epidermis; UVA reaches the dermis."),
        ("PUVA", "Psoralen intercalates in DNA; UVA cross-links it, stopping cell division."),
        ("Delivery", "Treatment is given in controlled whole-body cabinets.", "v3-nbuvb-cabinet.jpg", "Narrowband UVB cabinet.")],
  comp=["Irritation (vitamin D, tar), hypercalcaemia (excess calcipotriol), burning, photoageing, skin cancer (PUVA > UVB)."],
  prog=["Good clearance in many; remissions last months."],
  see_also=["psoriasis", "biologics-systemics", "eczema-dermatitis", "topical-corticosteroids", "hypopigmentation-skin-of-colour"])

E('acne-prescribing-combined-pill',
  titles=T,
  kf=["NICE NG198: first-line acne treatment is a **12-week fixed-combination topical** (adapalene + benzoyl peroxide, tretinoin + clindamycin, or BPO + clindamycin).",
      "Add an oral **tetracycline (lymecycline or doxycycline)** with a topical for moderate–severe acne; never use oral and topical antibiotics together.",
      "The **combined oral contraceptive (COC)** is an alternative or add-on for women; choose using **UKMEC** (VTE, migraine with aura, smoking over 35).",
      "Co-cyprindiol has higher VTE risk: use only if other options fail and stop 3 months after acne control.",
      "Review at 12 weeks; refer scarring, severe or persistent acne for isotretinoin."],
  myths=["**\"The pill causes acne\"**: progestogen-only methods can worsen acne; combined pills usually improve it."],
  patho_lead="The COC reduces acne by **lowering free androgen**, which drives sebum production.",
  mech=[("Ovarian suppression", "Ethinylestradiol and progestogen suppress ovulation and ovarian androgen output."),
        ("Raised SHBG", "Oestrogen increases sex hormone–binding globulin, reducing free testosterone."),
        ("Less sebum", "Lower androgen activity shrinks sebaceous output and comedone formation.", "v3-acne-follicle-stages.jpg", "Acne develops from microcomedone to inflamed lesion."),
        ("Anti-androgenic progestogens", "Cyproterone, drospirenone and others block androgen receptors.", "v3-jawline-acne.jpg", "Hormonal pattern acne along the jawline.")],
  comp=["VTE (higher with co-cyprindiol, drospirenone, desogestrel than levonorgestrel), breakthrough bleeding, mood change."],
  prog=["Benefit takes 3–6 months."],
  see_also=["acne-vulgaris", "retinoids", "hirsutism", "acne-scars"])

E('drug-eruption-approach',
  kf=["Drug reactions are common: first **classify the morphology** (maculopapular, urticarial, blistering, pustular, fixed, photosensitive, lichenoid).",
      "Build a **drug timeline**: everything started in the last 8 weeks, including OTC and herbal products.",
      "Latency clues: urticaria/anaphylaxis minutes–hours; AGEP hours–2 days; MDE 4–14 days; SJS/TEN 4–28 days; DRESS 2–8 weeks.",
      "Red flags: **mucosal involvement, skin pain, blisters, facial oedema, fever, organ dysfunction**: same-day referral.",
      "Stop the likely culprit, document the reaction precisely, Yellow Card serious reactions, and refer for allergy testing when it matters."],
  myths=["**\"Any rash on amoxicillin = penicillin allergy\"**: many are viral or non-allergic; mislabelled allergy harms future care."],
  patho_lead="Drug reactions follow **different immune pathways**, which explain their timing and appearance.",
  mech=[("Type I (IgE)", "Mast cell degranulation within minutes: urticaria, angioedema, anaphylaxis."),
        ("Type IV T-cell reactions", "Delayed days to weeks: maculopapular (IVb/c), SJS/TEN (IVc), AGEP (IVd), DRESS (IVb)."),
        ("p-i concept", "Some drugs bind HLA or T-cell receptors directly; HLA alleles predict risk (HLA-B*58:01, B*15:02, B*57:01)."),
        ("Non-immune", "Phototoxicity, pigmentation and pharmacological effects (NSAID-exacerbated urticaria).")],
  comp=["SJS/TEN, DRESS, anaphylaxis; mislabelled allergies."],
  prog=["Most simple drug rashes resolve in 1–2 weeks after stopping the drug."],
  see_also=["morbilliform-drug-eruption", "drug-induced-blistering", "dress", "agep", "fixed-drug-eruption"])

E('blistering-approach',
  kf=["Sort blisters by **level of split**: intraepidermal (flaccid, erosions: pemphigus, impetigo, SSSS, SJS/TEN) vs subepidermal (tense: pemphigoid, DH, PCT, EBA).",
      "Ask: age, acute or chronic, mucosa, itch vs pain, drugs, sites, systemic illness.",
      "Emergencies: **SJS/TEN, SSSS, extensive pemphigus, eczema herpeticum, neonatal blistering**.",
      "Investigations: swab (bacteria, HSV PCR), skin biopsy of a fresh blister edge plus perilesional skin for **direct immunofluorescence**, serology.",
      "Common causes in primary care: impetigo, insect bites, friction, contact dermatitis, pompholyx, herpes."],
  myths=["**\"Blisters are always infection\"**: autoimmune and drug causes need biopsy and urgent referral."],
  patho_lead="Where the skin **splits** decides how a blister looks.",
  mech=[("Subcorneal / intraepidermal", "Fragile roof breaks easily: erosions and crusts (bullous impetigo, pemphigus foliaceus)."),
        ("Suprabasal", "Desmosome loss in pemphigus vulgaris: flaccid blisters, mucosal erosions."),
        ("Subepidermal", "Basement membrane damage (pemphigoid, DH, PCT, EBA): tense blisters.", "v3-bp-vs-pv-split.jpg", "Intraepidermal (flaccid) versus subepidermal (tense) blister."),
        ("Full-thickness necrosis", "SJS/TEN: the whole epidermis dies and sloughs.", "v4-ten-necrosis.jpg", "TEN: full-thickness epidermal necrosis.")],
  comp=["Infection, fluid loss, scarring, mucosal strictures."],
  prog=["Depends on cause."],
  see_also=["bullous-pemphigoid", "pemphigus", "dermatitis-herpetiformis", "drug-induced-blistering", "impetigo"])

E('annular-rashes',
  kf=["Ring-shaped (**annular**) rashes have many causes: **tinea** (scaly active edge), granuloma annulare (no scale), erythema migrans, urticaria, pityriasis rosea herald patch, erythema multiforme, discoid eczema, subacute lupus, psoriasis, sarcoidosis.",
      "Key questions: **scale?** (where), duration of each lesion, itch, symptoms, sun exposure, tick bites, drugs.",
      "Scale at the advancing edge with central clearing: scrape for fungus before steroid.",
      "Trailing scale inside the edge: pityriasis rosea or erythema annulare centrifugum.",
      "Annular lesions lasting <24 h: urticaria; >24 h with bruising: urticarial vasculitis."],
  myths=["**\"Every ring is ringworm\"**: granuloma annulare and other rings are commonly mistaken for tinea."],
  patho_lead="Rings form when a process **spreads outwards while the centre heals**.",
  mech=[("Centrifugal spread", "Fungi, bacteria or immune activity move outwards; the centre resolves."),
        ("Edge vs centre", "Active inflammation and organisms sit at the edge.", "v3-ga-vs-tinea-ring.jpg", "Granuloma annulare (smooth, no scale) versus tinea (scaly edge)."),
        ("Scale position", "Leading-edge scale (tinea) vs trailing collarette (pityriasis rosea).", "v3-collarette-vs-tinea-edge.jpg", "Collarette scale versus tinea edge.")],
  comp=["Misdiagnosis (tinea incognito after steroids)."],
  prog=["Depends on cause."],
  see_also=["tinea", "pityriasis-rosea", "lyme-disease", "urticaria-angioedema", "erythema-multiforme"])

E('lesion-language',
  overview_pre=["This page is a **reference for dermatological terms**: how to describe lesions precisely so that a description alone points to a diagnosis."],
  kf=["Describe: **site, number, distribution, configuration, size, shape, colour, surface, palpation** (SCALP-style).",
      "Primary lesions: macule/patch (flat), papule/plaque (raised, solid), nodule (deep), vesicle/bulla (fluid), pustule (pus), wheal (transient oedema).",
      "Secondary changes: scale, crust, erosion, ulcer, excoriation, lichenification, atrophy, scar.",
      "Configurations: annular, linear (Koebner, Blaschko), grouped (herpetiform), target, reticulate, serpiginous.",
      "Size thresholds: macule/papule under 1 cm (some use 0.5 cm); vesicle under 0.5 cm vs bulla."],
  myths=["**\"Rash\" is a description**: precise terms change the differential diagnosis."],
  comp=["Miscommunication in referrals and teledermatology."],
  prog=["Not applicable."],
  see_also=["skin-layers-fitzpatrick", "teledermatology", "annular-rashes", "blistering-approach"])

E('skin-layers-fitzpatrick',
  overview_pre=["This page covers **skin structure and skin typing**: the basis for interpreting lesions, dermoscopy and treatment risk."],
  kf=["Skin layers: **epidermis** (keratinocytes, melanocytes, Langerhans cells, Merkel cells), **dermis** (collagen, vessels, nerves, adnexa) and **subcutis** (fat).",
      "Epidermis renews about every **28 days**: basal → spinous → granular → stratum corneum.",
      "**Fitzpatrick types I–VI** describe burning vs tanning: I always burns, never tans; VI never burns.",
      "Fitzpatrick type predicts sunburn and skin-cancer risk, and risk of pigment change, keloids and procedure complications.",
      "The depth of a process explains colour: superficial pigment looks brown, deep pigment blue-grey (Tyndall)."],
  myths=["**\"Dark skin doesn't need sun protection\"**: risk is lower but not zero; acral melanoma and pigmentation still matter."],
  patho_lead="Each layer has **its own cells and diseases**, so knowing depth explains what you see.",
  mech=[("Epidermis", "Keratinocytes mature upwards and shed; melanocytes pass pigment to them."),
        ("Dermo-epidermal junction", "Basement membrane anchors epidermis to dermis (target in pemphigoid)."),
        ("Dermis", "Collagen and elastin give strength; vessels, nerves, follicles and glands sit here."),
        ("Subcutis", "Fat lobules separated by septa (panniculitis sites).")],
  comp=["Not applicable."],
  prog=["Not applicable."],
  see_also=["lesion-language", "hypopigmentation-skin-of-colour", "melanoma", "polymorphic-light-eruption"])
